import { test, expect } from 'vitest';
import { supabaseClient } from '../utils/mockSupabase';
import { appendChangeLog } from './repo';

const mockInsert = supabaseClient.from('changelog').insert;

describe('appendChangeLog', () => {
  test('should omit id in insert payload', async () => {
    const data = { message: 'test', campaign_id: 'campaign-123' };
    await appendChangeLog(data);
    expect(mockInsert).toHaveBeenCalledWith({
      message: 'test',
      campaign_id: 'campaign-123'
    });
  });

  test('should propagate insert errors', async () => {
    mockInsert.mockRejectedValueOnce(new Error('Database error'));
    await expect(appendChangeLog({})).rejects.toThrow('Database error');
  });
});

